export class GalleriaComponent {
  constructor(galleriaService, breakpointObserver) {
    this.galleriaService = galleriaService;
    this.breakpointObserver = breakpointObserver;
    this.images = [];
    this.cols = 2;
  }
  ngOnInit() {
    this.setupGrid();
    this.fetchImages();
  }
  setupGrid() {
    this.breakpointObserver.observe([Breakpoints.XSmall, Breakpoints.Small, Breakpoints.Medium, Breakpoints.Large]).subscribe(result => {
      this.cols = result.breakpoints[Breakpoints.XSmall] ? 1 : result.breakpoints[Breakpoints.Small] ? 2 : result.breakpoints[Breakpoints.Medium] ? 3 : 4;
    });
  }
  fetchImages() {
    this.galleriaService.getGeneratedImages(20, 0).subscribe({
      next: data => this.images = data,
      error: err => console.error(err)
    });
  }
}
